using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using LWS.TruckTaxi;
namespace LWS.TruckTerrierRacing.Editor {
public static class TerrierCrowdAuthoring {
 public static void Install(TerrierMatch m){var old=GameObject.Find("Pooled Terrier track runners");if(old!=null)UnityEngine.Object.DestroyImmediate(old);var c=m.GetComponent<TerrierCrowd>()??m.gameObject.AddComponent<TerrierCrowd>();m.crowd=c;c.match=m;c.runners=new TerrierRunner[10];c.paths=new WalkPath[10];c.ghosts=new Transform[10];var root=new GameObject("Pooled Terrier track runners");for(int i=0;i<10;i++){var pathRoot=new GameObject("UTS closed crossing path "+i);pathRoot.transform.SetParent(root.transform,false);var path=pathRoot.AddComponent<WalkPath>();path.loopPath=true;path.disableLineDraw=true;path.numberOfWays=1;for(int k=0;k<4;k++){var point=new GameObject("Crossing waypoint "+k);point.transform.SetParent(pathRoot.transform,false);point.transform.position=m.course.World(new Vector3(k<2?-10:10,0,20+i*12.6f+(k==0||k==3?-1.8f:1.8f)));path.pathPointTransform.Add(point);path.pathPoint.Add(point.transform.position);}c.paths[i]=path;string source="Assets/LWS/TruckTaxi/Prefabs/Pedestrians/"+(i%2==0?"Taxi_Girl_11":"Taxi_Girl_22")+".prefab";var person=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(source));PrefabUtility.UnpackPrefabInstance(person,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);person.name="Player track runner "+i;person.transform.SetParent(root.transform,false);person.transform.position=path.pathPoint[0];var body=person.GetComponent<Rigidbody>();body.interpolation=RigidbodyInterpolation.Interpolate;var movement=person.AddComponent<MovePath>();movement.walkPath=path;movement.loop=true;movement.forward=true;var walker=person.AddComponent<Passersby>();walker.ANIMATION_STATE=PeopleAnimState.run;walker.RUN_SPEED=4.2f;walker.WALK_SPEED=1.5f;walker.SPEED_ROTATION=5;walker.VIEW_RADIUS=0;walker.targetMask=0;var pedestrian=person.AddComponent<TruckTaxiPedestrian>();pedestrian.settings=new TruckTaxiPedestrianImpactSettings{minimumRagdollImpactSpeed=2,impactForceMultiplier=18,maximumRagdollImpulse=260,upwardImpulse=55,ragdollLifetime=6,angularImpulse=2};var runner=person.AddComponent<TerrierRunner>();runner.crowd=c;runner.pedestrian=pedestrian;runner.walker=walker;runner.movement=movement;runner.slot=i;var trigger=person.AddComponent<CapsuleCollider>();var sourceShape=person.GetComponents<CapsuleCollider>().First(x=>x!=trigger);trigger.center=sourceShape.center;trigger.radius=sourceShape.radius+.3f;trigger.height=sourceShape.height+.3f;trigger.isTrigger=true;runner.detector=trigger;foreach(var t in person.GetComponentsInChildren<Transform>(true))t.gameObject.layer=2;c.runners[i]=runner;
 var ghost=new GameObject("Player recorded runner ghost "+i);ghost.transform.SetParent(root.transform,false);var copy=UnityEngine.Object.Instantiate(person,ghost.transform,false);foreach(var joint in copy.GetComponentsInChildren<Joint>(true))UnityEngine.Object.DestroyImmediate(joint);foreach(var component in copy.GetComponentsInChildren<Component>(true))if(!(component is Transform)&&!(component is Renderer)&&!(component is MeshFilter))UnityEngine.Object.DestroyImmediate(component);foreach(var t in copy.GetComponentsInChildren<Transform>(true))t.gameObject.layer=0;c.ghosts[i]=ghost.transform;ghost.SetActive(false);}EditorUtility.SetDirty(c);EditorUtility.SetDirty(m);}
}
